                        abstract key: PropertyKey with get

                    [<Import("../core/standard-schema.cjs.StandardSchemaV1", "SuccessResult")>]
                    type SuccessResult<'Output> =
                        abstract issues: option<unit> with get
                        abstract value: 'Output with get

