                    module rec Props =
                        [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
                        type Version = | [<CompiledValue(1)>] ``1``

                    [<Import("../core/standard-schema.cjs.StandardTypedV1", "Types")>]
                    type Types<'Output, 'Input> =
                        abstract output: 'Output with get
                        abstract input: 'Input with get

                    [<Import("../core/standard-schema.cjs.StandardTypedV1", "Props")>]
                    type Props<'Output, 'Input> =
